python3 - <<'PY'
p='src/types/checker/inference/objects/methods.rs'
s=open(p).read()
old = """                        // A BY-REFERENCE parameter never adopts the call site's element type:
                        // the callee writes into the CALLER's storage, and a body compiled for
                        // `array<int>` that widens mid-call rewrites that storage to boxed slots
                        // while the caller still reads raw ones. `$o->go($ints)` printed
                        // ADDRESSES for exactly that reason.
                        let by_ref = sig.ref_params.get(i).copied().unwrap_or(false);
                        let current = sig.params[i].1.clone();
                        sig.params[i].1 = if by_ref {
                            Self::by_ref_array_param_type(&current, arg_ty)
                                .unwrap_or(current)
                        } else {
                            Self::specialize_generic_array_param_hint(&current, arg_ty)
                        };"""
new = """                        // A BY-REFERENCE parameter the method pass already WIDENED keeps that
                        // type: it is what the caller's storage now holds, and re-narrowing it
                        // here would hand a body compiled for raw slots an array of boxes.
                        // `$o->go($ints)` printed ADDRESSES for the mirror of this mistake. A
                        // by-reference parameter the body does not widen still specializes, so a
                        // method that only sorts its argument stays on slots the backend sorts.
                        let by_ref = sig.ref_params.get(i).copied().unwrap_or(false);
                        let current = sig.params[i].1.clone();
                        if !(by_ref && by_ref_param_is_widened(&current)) {
                            sig.params[i].1 =
                                Self::specialize_generic_array_param_hint(&current, arg_ty);
                        }"""
n = s.count(old)
assert n == 3, n
s = s.replace(old, new)
s = s.rstrip() + """

/// Returns whether a by-reference array parameter already carries boxed element slots.
///
/// The method pass records that when a body widens one (`method_pass::
/// update_method_by_ref_param_types`), and a later call site must not undo it.
fn by_ref_param_is_widened(param_ty: &PhpType) -> bool {
    match param_ty.codegen_repr() {
        PhpType::Array(elem) => elem.codegen_repr() == PhpType::Mixed,
        PhpType::AssocArray { value, .. } => value.codegen_repr() == PhpType::Mixed,
        _ => false,
    }
}
"""
open(p,'w').write(s)
print('method paths made consistent')
